record.field:
SO = env['sale.order'].sudo()
Att = env['ir.attachment'].sudo()
Obra = env['x_automa_obra'].sudo()
Plano = env['x_recorrido_plano'].sudo()
Rec = env['x_automa_recorrido'].sudo()
excluir = env.context.get('excluir_planos') or []
# El plano único de la v1.7 pasa a la lista de planos de la orden.
for so in SO.search([('x_plano', '!=', False)]):
    datos, nom = so.x_plano, so.x_plano_name
    so.write({'x_plano': False, 'x_plano_name': False})
    Plano.create({'x_order_id': so.id, 'x_name': 'Canalizaciones', 'x_archivo': datos, 'x_archivo_name': nom or 'Plano.pdf'})
tipos = {'canalizaciones': 'Canalizaciones', 'iluminacion': 'Iluminación', 'especiales': 'Especiales', 'trayectorias': 'Trayectorias'}
# v1.8.6: el tipo de plano (Especiales, Canalizaciones…) pasa a la descripción; el tipo ahora es el formato (PDF, DWG).
for pl in Plano.search(['|', ('x_tipo_id', '!=', False), ('x_tipo', '!=', False)]):
    if pl.x_tipo_id:
        nombre_tipo = pl.x_tipo_id.x_name
    elif pl.x_tipo == 'otro':
        nombre_tipo = pl.x_tipo_texto or ''
    else:
        nombre_tipo = tipos.get(pl.x_tipo, '')
    desc = pl.x_name if pl.x_name and pl.x_name != pl.x_archivo_name else ''
    if nombre_tipo and desc.lower() != nombre_tipo.lower():
        desc = '%s - %s' % (nombre_tipo, desc) if desc else nombre_tipo
    pl.write({'x_name': desc or pl.x_archivo_name or 'Plano', 'x_tipo_id': False, 'x_tipo': False, 'x_tipo_texto': False})
# Recorridos de antes de la v1.8.8 (sin plano ligado): si su orden tiene un solo plano PDF, es ese.
for so in Rec.search([('x_plano_id', '=', False), ('x_order_id', '!=', False)]).mapped('x_order_id'):
    pdfs = so.x_plano_ids.filtered(lambda x: (x.x_archivo_name or '').lower().endswith('.pdf'))
    if len(pdfs) == 1:
        Rec.search([('x_plano_id', '=', False), ('x_order_id', '=', so.id)]).write({'x_plano_id': pdfs.id})
items = []
keep = []
for so in SO.search([('x_plano_ids', '!=', False)], order='date_order desc'):
    obra = Obra.search([('x_order_id', '=', so.id)], limit=1)
    if obra and obra.x_estado in ('completado', 'cancelado'):
        continue
    planos = []
    for pl in so.x_plano_ids:
        # Solo los PDF van a la app (aquí también se pueden guardar DWG u otros archivos).
        if pl.id in excluir or not pl.x_archivo or not (pl.x_archivo_name or '').lower().endswith('.pdf'):
            continue
        src = Att.search([('res_model', '=', 'x_recorrido_plano'), ('res_id', '=', pl.id), ('res_field', '=', 'x_archivo')], limit=1)
        version = src.checksum or str(pl.write_date)
        nombre = 'automa_plano_%s.js' % pl.id
        att = Att.search([('name', '=', nombre), ('res_model', '=', 'x_automa_obra'), ('res_id', '=', 0)], limit=1)
        if not att or att.description != version:
            js = 'window.__automaPlano(%d,"%s");' % (pl.id, pl.x_archivo.decode())
            vals = {'raw': js.encode(), 'mimetype': 'text/javascript', 'description': version}
            if att:
                att.write(vals)
            else:
                att = Att.create(dict(vals, name=nombre, res_model='x_automa_obra', res_id=0))
        token = att.generate_access_token()[0]
        keep.append(att.id)
        # Último recorrido de este plano (de cualquier técnico): la app lo ofrece para seguir desde ahí.
        ultimo = False
        for r in Rec.search([('x_plano_id', '=', pl.id)], order='x_fecha desc, id desc', limit=10):
            if r.x_pdf:
                src_r = Att.search([('res_model', '=', 'x_automa_recorrido'), ('res_id', '=', r.id), ('res_field', '=', 'x_pdf')], limit=1)
                v_r = src_r.checksum or str(r.write_date)
                nom_r = 'automa_rec_%s.js' % pl.id
                att_r = Att.search([('name', '=', nom_r), ('res_model', '=', 'x_automa_obra'), ('res_id', '=', 0)], limit=1)
                if not att_r or att_r.description != v_r:
                    vals_r = {'raw': ('window.__automaRecorrido(%d,"%s");' % (pl.id, r.x_pdf.decode())).encode(), 'mimetype': 'text/javascript', 'description': v_r}
                    if att_r:
                        att_r.write(vals_r)
                    else:
                        att_r = Att.create(dict(vals_r, name=nom_r, res_model='x_automa_obra', res_id=0))
                keep.append(att_r.id)
                ultimo = {'fecha': str(r.x_fecha or ''), 'tecnico': r.x_tecnico or '', 'url': '/web/content/%d?access_token=%s' % (att_r.id, att_r.generate_access_token()[0]), 'v': v_r}
                break
        planos.append({
            'id': pl.id,
            'tipo': pl.x_name or (pl.x_archivo_name or 'Plano').rsplit('.', 1)[0],
            'nombre': '',
            'archivo': pl.x_archivo_name or 'Plano.pdf',
            'plano': '/web/content/%d?access_token=%s' % (att.id, token),
            'v': version,
            'ultimo': ultimo,
        })
    if not planos:
        continue
    items.append({
        'order_id': so.id,
        'orden': so.name,
        'obra': obra.x_name if obra else (so.client_order_ref or so.partner_id.name or so.name),
        'cliente': so.partner_id.name or '',
        'planos': planos,
    })
Att.search(['|', ('name', '=like', 'automa_plano_%.js'), ('name', '=like', 'automa_rec_%.js'), ('res_model', '=', 'x_automa_obra'), ('id', 'not in', keep)]).unlink()
cat = env.ref('automa_recorridos.catalogo_planos').sudo()
cat.write({'raw': ('window.__automaPlanos(%s);' % json.dumps(items)).encode(), 'mimetype': 'text/javascript'})

if 'x_automa_plano' not in env or not env.ref('automa_planos.action_enviar_firma', raise_if_not_found=False):
    raise UserError('Para mandar a firmar necesitas el módulo Planos (firma) instalado.')
rec = record.with_context(bin_size=False)
if not rec.x_archivo or not (rec.x_archivo_name or '').lower().endswith('.pdf'):
    raise UserError('Solo se pueden mandar a firmar planos en PDF.')
so = rec.x_order_id
P = env['x_automa_plano'].with_context(bin_size=False)
pl = P.browse(rec.x_firma_id).exists() if rec.x_firma_id else P
if pl and pl.x_estado == 'firmado' and pl.x_pdf == rec.x_archivo:
    raise UserError('Este plano ya está firmado. Si subes un archivo nuevo, lo puedes volver a mandar.')
obra = env['x_automa_obra'].search([('x_order_id', '=', so.id)], limit=1)
proyecto = '%s - %s' % (obra.x_name if obra else (so.client_order_ref or so.partner_id.name or so.name), rec.x_name or 'Plano')
fname = (rec.x_name or 'Plano').replace('/', '-')
if not fname.lower().endswith('.pdf'):
    fname += '.pdf'
vals = {'x_name': proyecto, 'x_partner_id': so.partner_id.id, 'x_pdf_filename': fname}
if not pl or pl.x_pdf != rec.x_archivo:
    vals['x_pdf'] = rec.x_archivo
if pl:
    pl.write(vals)
else:
    vals['x_fecha'] = datetime.date.today()
    pl = P.create(vals)
    rec.write({'x_firma_id': pl.id})
action = env.ref('automa_planos.action_enviar_firma').with_context(active_model='x_automa_plano', active_id=pl.id, active_ids=[pl.id]).run()

if 'x_automa_plano' not in env or not record.x_firma_id:
    raise UserError('Este plano no se ha mandado a firmar.')
action = env.ref('automa_planos.action_ver_firmado').with_context(active_model='x_automa_plano', active_id=record.x_firma_id, active_ids=[record.x_firma_id]).run()
